TLM.f("Tempora/Pent10-4",{"officium":"Feria quinta infra Hebdomadam X post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent10-0","from":{"Introitus":"Tempora/Pent10-0","Oratio":"Tempora/Pent10-0","Lectio":"Tempora/Pent10-0","Graduale":"Tempora/Pent10-0","Evangelium":"Tempora/Pent10-0","Offertorium":"Tempora/Pent10-0","Secreta":"Tempora/Pent10-0","Communio":"Tempora/Pent10-0","Postcommunio":"Tempora/Pent10-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 54:17-20; 54:23"},{"k":"text","la":"Dum clamárem ad Dóminum, exaudívit vocem meam, ab his, qui appropínquant mihi: et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet."},{"k":"ref","la":"Ps 54:2-3"},{"k":"text","la":"Exáudi, Deus, oratiónem meam, et ne despéxeris deprecatiónem meam: inténde mihi et exáudi me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dum clamárem ad Dóminum, exaudívit vocem meam, ab his, qui appropínquant mihi: et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet."}],"Oratio":[{"k":"text","la":"Deus, qui omnipoténtiam tuam parcéndo máxime et miserándo maniféstas: multíplica super nos misericórdiam tuam; ut, ad tua promíssa curréntes, cœléstium bonórum fácias esse consórtes."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 12:2-11"},{"k":"text","la":"Fratres: Scitis, quóniam, cum gentes essétis, ad simulácra muta prout ducebámini eúntes. Ideo notum vobisfacio, quod nemo in Spíritu Dei loquens, dicit anáthema Jesu. Et nemo potest dícere, Dóminus Jesus, nisi in Spíritu Sancto. Divisiónes vero gratiárum sunt, idem autem Spíritus. Et divisiónes ministratiónum sunt, idem autem Dóminus. Et divisiónes operatiónum sunt, idem vero Deus, qui operátur ómnia in ómnibus. Unicuíque autem datur manifestátio Spíritus ad utilitátem. Alii quidem per Spíritum datur sermo sapiéntiæ álii autem sermo sciéntiæ secúndum eúndem Spíritum: álteri fides in eódem Spíritu: álii grátia sanitátum in uno Spíritu: álii operátio virtútum, álii prophetía, álii discrétio spirítuum, álii génera linguárum, álii interpretátio sermónum. Hæc autem ómnia operátur unus atque idem Spíritus, dívidens síngulis, prout vult."}],"Graduale":[{"k":"ref","la":"Ps 16:8; 16:2"},{"k":"text","la":"Custódi me, Dómine, ut pupíllam óculi: sub umbra alárum tuárum prótege me."},{"k":"text","la":"De vultu tuo judícium meum pródeat: óculi tui vídeant æquitátem.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 64:2"},{"k":"text","la":"Te decet hymnus, Deus, in Sion: et tibi reddétur votum in Jerúsalem. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 18:9-14"},{"k":"text","la":"In illo témpore: Dixit Jesus ad quosdam, qui in se confidébant tamquam justi et aspernabántur céteros, parábolam istam: Duo hómines ascendérunt in templum, ut orárent: unus pharisǽus, et alter publicánus. Pharisǽus stans, hæc apud se orábat: Deus, grátias ago tibi, quia non sum sicut céteri hóminum: raptóres, injústi, adúlteri: velut étiam hic publicánus. Jejúno bis in sábbato: décimas do ómnium, quæ possídeo. Et publicánus a longe stans nolébat nec óculos ad cœlum leváre: sed percutiébat pectus suum, dicens: Deus, propítius esto mihi peccatóri. Dico vobis: descéndit hic justificátus in domum suam ab illo: quia omnis qui se exáltat, humiliábitur: et qui se humíliat, exaltábitur."}],"Offertorium":[{"k":"ref","la":"Ps 24:1-3"},{"k":"text","la":"Ad te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."}],"Secreta":[{"k":"text","la":"Tibi, Dómine, sacrifícia dicáta reddántur: quæ sic ad honórem nóminis tui deferénda tribuísti, ut eadem remédia fíeri nostra præstáres."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 50:21"},{"k":"text","la":"Acceptábis sacrificium justítiæ, oblatiónes et holocáusta, super altáre tuum, Dómine."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine, Deus noster: ut, quos divínis reparáre non désinis sacraméntis, tuis non destítuas benígnus auxíliis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"904d7e91b9e07e5e":{"t":"Ps 54, 17 i 19 i 20 i 23\n(Ps 54, 17 i 19 i 20 i 23) Dok sam zazivao Gospodina, uslišio je moj glas protiv onih koji mi se približuju. Ponizio ih je on koji je prije vjekova i ostaje u vijeke. Baci na Gospodina svoju brigu i on će te ishraniti. (Ps 54, 2-3) Usliši, Bože, molitvu moju i ne prezri prošnju moju, pogledaj na me i usliši me.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 54, 17 i 19 i 20 i 23) Dok sam zazivao Gospodina, uslišio je moj glas protiv onih koji mi se približuju. Ponizio ih je on koji je prije vjekova i ostaje u vijeke. Baci na Gospodina svoju brigu i on će te ishraniti.","kn":"(Ps. 54, 17-23). Kad sam vapio ka Gospodinu, uslišao je glas moj i oelobodio me od onih, koji mi se približivahu i ponizio ih je onaj, koji je prije vjekova i ostaje u vijeke; Gospodinu prepusti brige svoje i on će te obraniti. (Pš. 54, ' 2) Usiiši, Bože, molitvu moju, i ne prezri prošnje moje, pazđ ma me i saslušaj me. Slava Ocu . . . Kad sam...","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"fa5369ad3c3c67b1":{"t":"<i>Pomolimo se</i>.\nBože, koji svoju svemoć očituješ ponajviše u praštanju i milosrđu, prospi na nas svoje milosrđe, da one koji hite k tvojim obećanjima učiniš dionicima nebeskih dobara.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji svemogučnost svoju najviše očituješ opraštajući i milujući, umnoži nad nama milosrđe svoje, da učiniš dionicima ncibesklh darove. one, koji idu za tvojim obećanjima, po G. n.","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"b09b148a982834ab":{"t":"1 Kor 12, 2-11\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, znate, dok ste bili nevjernici, da ste išli kako su vas vodili k nijemim idolima. Zato vam kažem, da nitko tko govori u Božjem Duhu, ne kaže: Prokletstvo Isusu! I nitko ne može priznavati Isusa Gospodinom nego u Duhu Svetom. Različiti su darovi, ali je isti Duh; i službe su različite, ali je Gospodin isti; i djela su različita, ali jedan te isti Bog djeluje u svima. Svakomu se daje objava Duha na korist sviju. Jednome se po Duhu daje mudrost, drugome po istom Duhu znanje; jednome po istom Duhu živa vjera, drugome po istom Duhu milost liječenja; jednome moć čudesa, drugome dar proricanja; jednome da razlikuje duhove, drugome da govori različitim jezicima, trećemu da tumači govore. Sve to čini jedan te isti Duh, koji svakome dijeli kako hoće.","kn":"Čitanje pt^Ianice hl. Favla apostola Korinćanima (I, 12, 2-11). Braćo! Znate, dok ste bili neznabošci, da ste išli, kako , su vas .vodili, k. nijemim idolima. Zato vam javljam, da. nitko, koji govori u Božjem Duhu, ne kaže: Anatema. Isusu. I nitko ne može kazati: Gospodin Isus, nego u Duhu Svetomu. Darovi su različiti, ali j e isti Duh. I službe su različite, ali je isti Gospodin. . I djela su različita, ali jedan te isti Bog djeluje u svirha. A objava se Duha daje svakomu na korist. Jednomu se po Duhu daje riječ mudrosti, a drugomu riječ znano- sti po istomu Duhu. Jednomu vjera u istom Duhu, a drugomu milost, da liječi u jednom Duhu. Jednomu, da tvori čudesa, a drugomu se daje dar proroštva, jednomu, da razlikuje duhove, drugomu, da govori različitim jezicima, drugomu opet, da tumači govore. A sve ovo čini jedan isti Duh, koji svakomu dijeli, kako hoće.","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"a3d4b5cf95090a09":{"t":"Ps 16, 8 i 2\nČuvaj me, Gospodine, kao zjenicu oka. Sakrij me pod sjenu svojih krila. Od tvojega lica nek izađe moj sud. Tvoje oči vide što je pravo.\n\nPs 64, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nTebi, Gospodine, dolikuje hvalospjev na Sionu, tebi neka se izvrši zavjet u Jeruzalemu. <i>Aleluja</i>.","kn":"(Ps. 16, 2). Čuvaj me. Gospodine, kao zjenicu oka, zakloni me sjenom krila svojih. Sud moj neka iziđe od lica Tvojega; oči Tvoje neka gledaju pravdu.\n\nAleluja, aleluja. (Ps. 64. 2) Tebi, Bože, pripada hvala u Sionu, Tebi neka se izvršuje zavjet u Jeruzalemu. Aleluja.","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"660a83c890931bb0":{"t":"Lk 18, 9-14\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus onima koji su sebe držali pravednicima, a druge su prezirali ovu usporedbu: Dva čovjeka pođu u hram na molitvu. Jedan je od njih bio farizej, a drugi carinik. Farizej je, stojeći, ovako molio u sebi: Bože zahvaljujem ti, što ja nisam kao ostali ljudi: razbojnici, nepravednici, preljubnici, ili kao ovaj carinik. Postim dva puta u sedmici i dajem desetinu od svakog prihoda. A carinik je stajao podalje i nije se usudio ni očiju podignuti k nebu, nego se udarao u prsa moleći; Bože, budi milostiv meni grješniku! Kažem vam: ovaj se vratio opravdan svojoj kući, a ne onaj. Jer svaki koji sam sebe uzvisuje ponizit će se, a tko se ponizuje uzvisit će se.","kn":"t Slijedi sveto evanđelje po Luki (18, 9-14). U ono vrijeme, kad su neki sebe držali pravednima, a druge su prezirali, reče Isus ovu prispodobu: Ušla su u hram, da se pomole, dva čovjeka: jedan farizej, a drugi ■ carinik. Farizej je stao i ovako u sebi molio: Hvala ti. Bože, što nijesam kao drugi ljudi: razbojnici, nepravednici, preljubnici ili kao i ovaj carinik. Postim dva puta u tjednu, od svega, što' imam, dajem desetinu. A carinik, koji je stajao izdaleka, nije htio ni očiju podignuti prema nebu, nego se udarao u prsa i govorio: Bože, budi milostiv meni grješniku! Kažem vam, da se ovaj vratio opravdan svojoj kući, a ne onaj. Jer svaki, koji se uzn'Osi, ponizit će se, a koji se pomizuje, uzvisit će se.","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"314b0585b7d97b62":{"t":"Ps 24, 1-3\nK tebi, Gospodine, uzdižem svoju dušu, Bože moj, u tebe se uzdam, ne daj da se postidim. Neka mi se ne rugaju neprijatelji, jer se neće smesti nitko od onih koji tebe čekaju.","kn":"(Ps. 24, 1-3). K Tebi, Gospodine, dižem dušu svoju; Bože moj, u Tebe se ufam, ne daj, da se zastidim i da mi se podsmijevaju neprijatelji moji, jer, koji Te čekaju, ne će se zastidjeti. r","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"072c2dc398fe714f":{"t":"Neka budu posvećeni tebi, Gospodine, darovi koje si dao da se tako prinose na čast tvojem imenu, da nama budu na lijek.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"; Da se izvrše Tebi, Gospodine, najmilije žrtve, koje dade da se prinose na čast imenu Tvojemu; podaj, da nas one i okrijepe, po G. n.","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"b318615739a9dfeb":{"t":"Ps 50, 21\nPrimat ćeš prave žrtve, prinose i paljenice na oltar svoj, Gospodine.","kn":"(Ps. 50, 21). Primit ćeš žrtvu pravde, prinose i paljenice na žrtveniku svojem, Gospoaine.","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"72319a1487183396":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine Bože naš, da u svojoj dobroti ne lišiš pomoći one, koje neprestano obnavljaš božanskim otajstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Molimo, Gospodine, Bože naš, da n-e ostaviš, dobrostiv, bez svojih pomoći onih, koje he prestaješ obnavljati božanstvenim tajnama, po G. H. \\","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"}}});
